/// f16->f32 lookup table (65536 f32 entries = 256KB), generated by build.rs.
/// Stored as aligned f32 array so the compiler can emit [table+idx*4] memory operand,
/// matching GCC's `vmulss xmm, xmm, DWORD PTR [r8+rax*4]` pattern.
#[repr(align(4))]
struct AlignedF16Table([u8; 65536 * 4]);

static F16_TABLE_BYTES: AlignedF16Table =
    AlignedF16Table(*include_bytes!(concat!(env!("OUT_DIR"), "/f16_table.bin")));

/// Convert f16 bits to f32 via lookup table -- zero-cost, one indexed load.
#[inline(always)]
pub fn f16_to_f32(bits: u16) -> f32 {
    // SAFETY: table has 65536 entries; bits (u16) is always a valid index 0..65535
    unsafe {
        let ptr = F16_TABLE_BYTES.0.as_ptr() as *const f32;
        ptr.add(bits as usize).read_unaligned()
    }
}

pub fn f32_to_f16(val: f32) -> u16 {
    let bits = val.to_bits();
    let sign = ((bits >> 31) & 1) as u16;
    let exp = ((bits >> 23) & 0xff) as i32;
    let mant = bits & 0x7fffff;

    if exp == 0xff {
        return (sign << 15) | (0x1f << 10) | ((mant >> 13) as u16 & 0x3ff);
    }

    let new_exp = exp - 127 + 15;

    if new_exp >= 31 {
        return (sign << 15) | (0x1f << 10);
    }

    if new_exp <= 0 {
        if new_exp < -10 {
            return sign << 15;
        }
        let m = (mant | 0x800000) >> (1 - new_exp + 13);
        return (sign << 15) | (m as u16 & 0x3ff);
    }

    // round-to-nearest-even (IEEE 754)
    let truncated = (mant >> 13) as u16 & 0x3ff;
    let remainder = mant & 0x1fff;
    let round_up = remainder > 0x1000 || (remainder == 0x1000 && (truncated & 1) != 0);
    let mut h = (sign << 15) | ((new_exp as u16) << 10) | truncated;
    if round_up {
        h += 1;
    }
    h
}

/// GELU lookup table: gelu(f32_from_f16(i)) stored as f16 bits (128KB).
/// Matches llama.cpp's ggml_table_gelu_f16 -- zero tanh/exp at inference time.
#[repr(align(2))]
struct AlignedGELUTable([u8; 65536 * 2]);

static GELU_TABLE_BYTES: AlignedGELUTable =
    AlignedGELUTable(*include_bytes!(concat!(env!("OUT_DIR"), "/gelu_table.bin")));

static GELU_QUICK_TABLE_BYTES: AlignedGELUTable =
    AlignedGELUTable(*include_bytes!(concat!(env!("OUT_DIR"), "/gelu_quick_table.bin")));

/// GELU via f16 lookup table -- f32->f16 index + one load, zero tanh/exp.
/// Matches llama.cpp ggml_vec_gelu_f32 table approach.
#[inline(always)]
pub fn gelu_f32_lut(x: f32) -> f32 {
    let f16_bits = f32_to_f16(x);
    // SAFETY: f16_bits is u16 (0..=65535), table has exactly 65536 entries.
    unsafe {
        let ptr = GELU_TABLE_BYTES.0.as_ptr() as *const u16;
        let result_f16 = ptr.add(f16_bits as usize).read_unaligned();
        f16_to_f32(result_f16)
    }
}

/// GELU-quick via f16 lookup table -- x * sigmoid(1.702*x), zero exp.
#[inline(always)]
pub fn gelu_quick_f32_lut(x: f32) -> f32 {
    let f16_bits = f32_to_f16(x);
    // SAFETY: f16_bits is u16 (0..=65535), table has exactly 65536 entries.
    unsafe {
        let ptr = GELU_QUICK_TABLE_BYTES.0.as_ptr() as *const u16;
        let result_f16 = ptr.add(f16_bits as usize).read_unaligned();
        f16_to_f32(result_f16)
    }
}

/// E8M0 half lookup table: 256 entries, value[i] = 2^(i-128) (= ggml_table_f32_e8m0_half).
/// Generated by build.rs, matching llama.cpp ggml_e8m0_to_fp32_half.
#[repr(align(4))]
struct AlignedE8M0HalfTable([u8; 256 * 4]);

static E8M0_HALF_TABLE: AlignedE8M0HalfTable =
    AlignedE8M0HalfTable(*include_bytes!(concat!(env!("OUT_DIR"), "/e8m0_half_table.bin")));

/// Convert E8M0 exponent byte to f32, divided by 2: 2^(x-128).
/// Matches llama.cpp GGML_CPU_E8M0_TO_FP32_HALF table lookup.
#[inline(always)]
pub fn e8m0_to_f32_half(x: u8) -> f32 {
    // SAFETY: table has 256 entries; x (u8) is always a valid index 0..255.
    unsafe {
        let ptr = E8M0_HALF_TABLE.0.as_ptr() as *const f32;
        ptr.add(x as usize).read_unaligned()
    }
}

/// UE4M3 lookup table: 256 entries (= ggml_table_f32_ue4m3).
/// Generated by build.rs, matching llama.cpp ggml_ue4m3_to_fp32.
/// Returns raw * 0.5 to match kvalues_mxfp4 convention (kvalues = 2 x E2M1_float).
#[repr(align(4))]
struct AlignedUE4M3Table([u8; 256 * 4]);

static UE4M3_TABLE: AlignedUE4M3Table =
    AlignedUE4M3Table(*include_bytes!(concat!(env!("OUT_DIR"), "/ue4m3_table.bin")));

/// Convert UE4M3 byte to f32 via lookup table.
/// Matches llama.cpp GGML_CPU_UE4M3_TO_FP32 table lookup.
/// Returns raw_value * 0.5 -- callers using KVALUES_MXFP4 (which are 2x E2M1) get the right product.
#[inline(always)]
pub fn ue4m3_to_f32(x: u8) -> f32 {
    // SAFETY: table has 256 entries; x (u8) is always a valid index 0..255.
    unsafe {
        let ptr = UE4M3_TABLE.0.as_ptr() as *const f32;
        ptr.add(x as usize).read_unaligned()
    }
}

/// Quantize a positive f32 scale to a UE4M3 byte (ggml_fp32_to_ue4m3 port).
/// Round-to-nearest on the 3-bit mantissa, subnormal encoding (man * 2^-9)
/// for scales below 2^-6, saturation at 448.0 (0x7E). Non-positive / NaN -> 0.
pub fn f32_to_ue4m3(x: f32) -> u8 {
    let mut x = x;
    if !(x > 0.0) {
        return 0;
    }
    if x > 448.0 {
        x = 448.0;
    }
    let bits = x.to_bits();
    let fp32_exp = ((bits >> 23) & 0xFF) as i32 - 127;
    let fp32_man = ((bits >> 20) & 0x7) as i32;
    let ue4m3_exp = fp32_exp + 7;
    if ue4m3_exp <= 0 {
        // subnormal: value = man * 2^-9, man = round(x * 2^9)
        let mut man = (x * 512.0 + 0.5) as i32;
        if man > 7 {
            man = 7;
        }
        if man < 1 {
            return 0;
        }
        return man as u8;
    }
    if ue4m3_exp >= 15 {
        return 0x7E;
    }
    let round_bit = ((bits >> 19) & 1) as i32;
    let mut ue4m3_man = fp32_man + round_bit;
    let mut ue4m3_exp = ue4m3_exp;
    if ue4m3_man > 7 {
        ue4m3_man = 0;
        ue4m3_exp += 1;
        if ue4m3_exp >= 15 {
            return 0x7E;
        }
    }
    ((ue4m3_exp << 3) | ue4m3_man) as u8
}

pub fn bf16_to_f32(bits: u16) -> f32 {
    f32::from_bits((bits as u32) << 16)
}

pub fn get_scale_min_k4(j: usize, scales: &[u8]) -> (u8, u8) {
    if j < 4 {
        (scales[j] & 63, scales[j + 4] & 63)
    } else {
        (
            (scales[j + 4] & 0xF) | ((scales[j - 4] >> 6) << 4),
            (scales[j + 4] >> 4) | ((scales[j] >> 6) << 4),
        )
    }
}

pub fn nearest_int(val: f32) -> i32 {
    assert!(val <= 4194303.0);
    let magic = 12582912.0f32; // 0x4B400000
    let val_plus_magic = val + magic;
    let bits = val_plus_magic.to_bits() as i32;
    bits - magic.to_bits() as i32
}

#[cfg(kani)]
mod kani_proofs {
    use super::*;

    #[kani::proof]
    fn f16_to_f32_no_panic() {
        let bits: u16 = kani::any();
        let _ = f16_to_f32(bits);
    }

    #[kani::proof]
    fn f16_to_f32_finite_for_normal() {
        let bits: u16 = kani::any();
        let exp = (bits >> 10) & 0x1f;
        kani::assume(exp > 0 && exp < 31);
        let result = f16_to_f32(bits);
        assert!(result.is_finite());
    }

    #[kani::proof]
    fn f32_to_f16_no_panic() {
        let val: f32 = kani::any();
        kani::assume(val.is_finite());
        let _ = f32_to_f16(val);
    }

    #[kani::proof]
    fn get_scale_min_k4_no_oob() {
        let j: usize = kani::any();
        kani::assume(j < 8);
        let scales: [u8; 12] = kani::any();
        let (s, m) = get_scale_min_k4(j, &scales);
        assert!(s <= 63);
        assert!(m <= 63);
    }

    #[kani::proof]
    fn nearest_int_no_panic() {
        let val: f32 = kani::any();
        kani::assume(val.is_finite());
        kani::assume(val.abs() < 4194303.0);
        kani::assume(val <= 4194303.0);
        let _ = nearest_int(val);
    }

    #[kani::proof]
    fn bf16_to_f32_no_panic() {
        let bits: u16 = kani::any();
        let _ = bf16_to_f32(bits);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ue4m3_decode_encode_roundtrips_exhaustively() {
        // Every canonical byte (0..=0x7F; the decode extracts exp/man from
        // the low 7 bits, and only 0x7F is the NaN slot) with exp < 15
        // decodes to a value that re-encodes to the same byte -- including
        // the subnormal range (exp==0) where amax/6 of typical transformer
        // weights lands. The encoder saturates at ue4m3_exp >= 15
        // (0x78..=0x7F are unreachable outputs), so those bytes cannot
        // round-trip by construction.
        for b in 0u16..=0x7F {
            let byte = b as u8;
            let v = ue4m3_to_f32(byte) * 2.0; // raw scale
            let re = f32_to_ue4m3(v);
            if byte == 0x7F {
                // NaN slot: decodes to 0, re-encodes to 0.
                assert_eq!(re, 0);
            } else if byte >= 0x78 {
                assert_eq!(re, 0x7E, "byte {byte:#04x} must saturate");
            } else {
                assert_eq!(re, byte, "byte {byte:#04x}: decoded {v}, re-encoded {re:#04x}");
            }
        }
        // ggml quirk: 0xFF is NOT the NaN slot (only 0x7F is), so it decodes
        // through the exp/man extraction as exp=15, man=7.
        assert_eq!(ue4m3_to_f32(0xFF), 240.0);
    }

    #[test]
    fn ue4m3_decode_spot_values() {
        assert_eq!(ue4m3_to_f32(0), 0.0);
        assert_eq!(ue4m3_to_f32(0x7F), 0.0);
        // subnormal: man * 2^-9, halved for the kvalues convention
        assert_eq!(ue4m3_to_f32(1), 1.0 / 1024.0);
        assert_eq!(ue4m3_to_f32(7), 7.0 / 1024.0);
        // normal: (1 + man/8) * 2^(exp-7), halved
        assert_eq!(ue4m3_to_f32(8), 0.5 / 64.0); // exp=1,man=0: 2^-6 / 2
        assert_eq!(ue4m3_to_f32(0x0F), 0.5 * (1.0 + 7.0 / 8.0) / 64.0);
        // max normal 0x7E: 448 / 2
        assert_eq!(ue4m3_to_f32(0x7E), 224.0);
    }

    #[test]
    fn ue4m3_encode_edge_cases() {
        assert_eq!(f32_to_ue4m3(0.0), 0);
        assert_eq!(f32_to_ue4m3(-1.0), 0);
        assert_eq!(f32_to_ue4m3(f32::NAN), 0);
        assert_eq!(f32_to_ue4m3(f32::INFINITY), 0x7E);
        assert_eq!(f32_to_ue4m3(1e30), 0x7E);
        assert_eq!(f32_to_ue4m3(448.0), 0x7E);
        // subnormal: 3 * 2^-9
        assert_eq!(f32_to_ue4m3(3.0 / 512.0), 3);
        // rounds to nearest: 5.5/8 mantissa step boundary
        assert_eq!(f32_to_ue4m3(1.0625), (7 << 3) | 1); // 1.125 = (1+1/8)*2^0
    }

    #[test]
    fn f16_roundtrip() {
        for &v in &[0.0f32, 1.0, -1.0, 0.5, 65504.0, 6.1e-5] {
            let h = f32_to_f16(v);
            let back = f16_to_f32(h);
            let rel = if v.abs() > 0.0 {
                ((back - v) / v).abs()
            } else {
                (back - v).abs()
            };
            assert!(
                rel < 0.002,
                "f16 roundtrip failed for {v}: got {back}, rel_err={rel}"
            );
        }
    }

    #[test]
    fn bf16_known_values() {
        assert_eq!(bf16_to_f32(0x3F80), 1.0);
        assert_eq!(bf16_to_f32(0x0000), 0.0);
        assert_eq!(bf16_to_f32(0xBF80), -1.0);
    }

    #[test]
    fn get_scale_min_k4_low_indices() {
        let scales = [10, 20, 30, 40, 50, 60, 70, 80, 0, 0, 0, 0];
        let (s, m) = get_scale_min_k4(0, &scales);
        assert_eq!(s, 10 & 63);
        assert_eq!(m, 50 & 63);
    }

    #[test]
    fn f16_f32_roundtrip_error_bounded() {
        use rand::Rng;
        use rand::SeedableRng;
        let mut rng = rand::rngs::StdRng::seed_from_u64(42);
        for _ in 0..10000 {
            let x: f32 = rng.random_range(-65504.0f32..=65504.0f32);
            let h = f32_to_f16(x);
            let back = f16_to_f32(h);
            if x.abs() > 1e-4 {
                let rel = ((back - x) / x).abs();
                assert!(
                    rel < 0.001,
                    "f16 roundtrip: x={x}, back={back}, rel_err={rel}"
                );
            }
        }
    }

    #[test]
    fn f16_preserves_sign() {
        use rand::Rng;
        use rand::SeedableRng;
        let mut rng = rand::rngs::StdRng::seed_from_u64(42);
        for _ in 0..10000 {
            let x: f32 = rng.random_range(-65504.0f32..=65504.0f32);
            if x == 0.0 {
                continue;
            }
            let h = f32_to_f16(x);
            let back = f16_to_f32(h);
            if back != 0.0 {
                assert_eq!(
                    x.is_sign_positive(),
                    back.is_sign_positive(),
                    "sign mismatch: x={x}, back={back}"
                );
            }
        }
    }

    #[test]
    fn f16_monotonic() {
        use rand::Rng;
        use rand::SeedableRng;
        let mut rng = rand::rngs::StdRng::seed_from_u64(42);
        for _ in 0..10000 {
            let a: f32 = rng.random_range(-65504.0f32..65504.0f32);
            let b: f32 = rng.random_range(a..=65504.0f32);
            if a >= b {
                continue;
            }
            let ha = f32_to_f16(a);
            let hb = f32_to_f16(b);
            let fa = f16_to_f32(ha);
            let fb = f16_to_f32(hb);
            assert!(
                fa <= fb,
                "monotonicity: a={a} -> f16 -> {fa}, b={b} -> f16 -> {fb}"
            );
        }
    }

    fn reference_gelu(x: f32) -> f32 {
        const SQRT_2_OVER_PI: f32 = 0.797_884_56;
        const GELU_COEF_A: f32 = 0.044715;
        0.5 * x * (1.0 + (SQRT_2_OVER_PI * x * (1.0 + GELU_COEF_A * x * x)).tanh())
    }

    fn reference_gelu_quick(x: f32) -> f32 {
        x * (1.0 / (1.0 + (-1.702_f32 * x).exp()))
    }

    #[test]
    fn gelu_lut_accuracy() {
        let test_vals = [
            -10.0f32, -5.0, -3.0, -2.0, -1.5, -1.0, -0.5, 0.0, 0.5, 1.0, 1.5, 2.0, 3.0, 5.0,
            10.0,
        ];
        for &x in &test_vals {
            let lut = gelu_f32_lut(x);
            let ref_val = reference_gelu(x);
            let err = (lut - ref_val).abs();
            let rel = if ref_val.abs() > 1e-4 {
                err / ref_val.abs()
            } else {
                err
            };
            assert!(
                rel < 1e-3,
                "gelu_lut({x}): lut={lut}, ref={ref_val}, rel_err={rel}"
            );
        }
    }

    #[test]
    fn gelu_quick_lut_accuracy() {
        let test_vals = [
            -10.0f32, -5.0, -3.0, -2.0, -1.5, -1.0, -0.5, 0.0, 0.5, 1.0, 1.5, 2.0, 3.0, 5.0,
            10.0,
        ];
        for &x in &test_vals {
            let lut = gelu_quick_f32_lut(x);
            let ref_val = reference_gelu_quick(x);
            let err = (lut - ref_val).abs();
            let rel = if ref_val.abs() > 1e-4 {
                err / ref_val.abs()
            } else {
                err
            };
            assert!(
                rel < 1e-3,
                "gelu_quick_lut({x}): lut={lut}, ref={ref_val}, rel_err={rel}"
            );
        }
    }

    #[test]
    fn nearest_int_rounds_correctly() {
        assert_eq!(nearest_int(0.5), 0);
        assert_eq!(nearest_int(1.5), 2);
        assert_eq!(nearest_int(2.5), 2);
        assert_eq!(nearest_int(0.7), 1);
        assert_eq!(nearest_int(-0.7), -1);
    }
}
